from pathlib import Path
from docx import Document
from docx.shared import Mm,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.opc.constants import RELATIONSHIP_TYPE as RT

B=Path(__file__).parent
(B/'output').mkdir(parents=True,exist_ok=True)
d=Document();s=d.sections[0]
s.page_width=Mm(210);s.page_height=Mm(297)
s.left_margin=Mm(25);s.right_margin=Mm(15);s.top_margin=Mm(20);s.bottom_margin=Mm(20)
s.header_distance=Mm(10);s.footer_distance=Mm(10)
for name in ['Normal','Title','Heading 1','Heading 2']:
    st=d.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
    st.element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Times New Roman')
normal=d.styles['Normal'];normal.font.size=Pt(14)
normal.paragraph_format.line_spacing=1.1;normal.paragraph_format.space_after=Pt(4)
normal.paragraph_format.first_line_indent=Mm(12.5)
d.styles['Title'].font.size=Pt(18);d.styles['Title'].font.bold=True
d.styles['Title'].paragraph_format.first_line_indent=Mm(0)
for name in ['Heading 1','Heading 2']:
    st=d.styles[name];st.font.size=Pt(14);st.font.bold=True
    st.paragraph_format.first_line_indent=Mm(0);st.paragraph_format.space_before=Pt(8)
    st.paragraph_format.space_after=Pt(4);st.paragraph_format.keep_with_next=True

def para(t):return d.add_paragraph(t)
def heading(t):d.add_heading(t,level=1)
def link(p,label,url):
    h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,RT.HYPERLINK,is_external=True))
    r=OxmlElement('w:r');pr=OxmlElement('w:rPr');sz=OxmlElement('w:sz');sz.set(qn('w:val'),'22');pr.append(sz)
    u=OxmlElement('w:u');u.set(qn('w:val'),'single');pr.append(u);r.append(pr)
    t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);p._p.append(h)

d.add_paragraph('Функциональная схема мотортестера',style='Title')
p=d.add_paragraph('Пояснение к проектной схеме Э2')
p.paragraph_format.first_line_indent=Mm(0)
para('Схема раскрывает прохождение сигнала и управление одноканальным прибором на STM32F103C8T6. В отличие от укрупнённой Э1, на Э2 отдельно показаны аналоговые функции, преобразование, перенос данных, память, управление записью, отсчёт времени и обмен с приложением. Прямоугольники обозначают функции; они не требуют отдельной микросхемы для каждого блока.')
para('Это проект конечного устройства, а не подтверждение готовности всех его частей. Стенд разрабатывается отдельно. Вход внешней синхронизации и управление катушкой в мотортестер не включены. Таймер, запускающий преобразования АЦП внутри микроконтроллера, сохраняется: он задаёт частоту выборок и не является внешней синхронизацией.')
heading('1 Измерительный аналоговый тракт')
para('Система зажигания — внешний объект измерения. Стрелка «Поле» означает ёмкостную связь с датчиком, а не прямое подключение к высоковольтной жиле.')
para('Ёмкостный съём преобразует изменение электрического поля в измеряемый сигнал. Его амплитуда и форма зависят от геометрии датчика, кабеля, установки и входной нагрузки. Конструкция и калибровка ещё требуют проверки.')
para('Входная защита ограничивает опасные для следующего каскада воздействия. Высокоомное согласование уменьшает нагрузку на датчик. На Э2 эти функции разделены для объяснения; их конкретная электрическая реализация и взаимное расположение уточняются при расчёте входа.')
para('Масштаб и смещение приводят сигнал к рабочему диапазону АЦП, включая размещение двуполярного сигнала относительно выбранного постоянного уровня. Этот уровень смещения не следует путать с опорным напряжением АЦП.')
para('Аналоговый фильтр ограничивает внеполосные составляющие до оцифровки. Драйвер АЦП обеспечивает требуемое установление сигнала на его входе. Параметры полосы, защиты и восстановления после большого импульса пока не утверждены; цифровая обработка аналоговый фильтр не заменяет.')

d.add_page_break()
heading('2 Функции STM32F103C8T6')
para('АЦП ADC1 преобразует аналоговый уровень в 12-разрядные коды. В существующем программном драйвере выбран канал 0, PA0. Это назначение MCU не является подтверждённой распиновкой разъёма конкретной платы.')
para('Таймер TIM3 задаёт моменты преобразования через внутренний сигнал TRGO. Он связан управляющей стрелкой с АЦП, а не включён последовательно в путь отсчётов. Команда управления записью разрешает или останавливает выборки.')
para('Перенос DMA доставляет коды АЦП в буфер оперативной памяти без копирования каждого кода процессором. В текущем драйвере DMA заполняет кольцо на 256 отсчётов; проверенная часть по 128 отсчётов передаётся программному ядру через отдельный снимок. DMA не заполняет итоговое окно напрямую.')
para('Буферы в ОЗУ временно хранят поток. Управление записью и выбор окна проверяет состояние захвата, принимает отсчёты и формирует сохраняемый результат. Итоговое окно текущего ядра содержит 2048 отсчётов; при готовности окна выборки останавливаются на время передачи. Поэтому непрерывность без пропусков между окнами не заявляется.')
para('Счётчик времени TIM2 используется для контроля сроков обслуживания и ошибок. Он не запускает АЦП. На схеме его связь направлена к управлению записью, отдельно от TIM3.')
para('Пакеты и состояния native USB FS объединяют подготовку данных, контроль целостности, сообщения о состоянии и собственный USB-контроллер MCU. Настройки и команды идут от ПК к управлению записью; отсчёты, метаданные и состояния — обратно. Внешний USB–UART-преобразователь не подразумевается.')
heading('3 Приложение и питание')
para('ПК с Windows 10 обеспечивает управление записью, просмотр графика и сохранение исходных отсчётов с метаданными. Независимое растяжение по времени и амплитуде меняет только вид графика, сохраняя исходные данные, единицы и калибровку. Это целевые функции полной системы; изображение двусторонней связи не означает завершённой интеграции текущих веток прошивки и приложения.')
para('Питание и опорные цепи обеспечивают аналоговый тракт и MCU. Выход подписан по назначению, без разведения всех питающих связей по листу. Источник, напряжения, фильтрация и развязка уточняются совместно с USB и платой. Пассивному ёмкостному съёму отдельное питание не назначено.')

d.add_page_break()
heading('4 Предусмотренные способы записи')
para('«Запись сейчас»: приложение передаёт команду, микроконтроллер принимает её и начинает новое окно без ожидания фронта измеряемого сигнала. Между нажатием кнопки и первым отсчётом имеется задержка передачи и выполнения команды. Точная привязка к событию внешнего стенда не обеспечивается.')
para('Однократный захват искры: по уточнению владельца от 12.10.2026 требуется один разряд целиком, включая горение и затухание, затем остановка. Это не промежуток между соседними искрами. Окно должно содержать начало разряда и достаточный запас после него; параметры запуска, предыстория, длительность и проверка полноты ещё должны быть обоснованы.')
para('Обычный однократный режим осциллографа означает один кадр выбранной длительности. Для новой функции рассматривается запуск по самому измеряемому сигналу с предысторией, без отдельного внешнего входа. Сам факт получения кадра не доказывает, что затухание полностью попало в запись. Текущие команды протокола сохраняют свою семантику до согласованного изменения.')
heading('5 Что уже проверено и что остаётся проектным')
para('Основание схемы: main 192fbb2ef9369bb1c32e11f97263094fca52763f и новое требование владельца от 12.10.2026. Структура ADC/TIM3/DMA/буферов/TIM2/USB сверена с исходниками. На этой основной версии приложение host/** является офлайн-просмотрщиком; целевая USB-интеграция рассматривается отдельно.')
para('Примитив «Запись сейчас» подготовлен отдельно в draft PR № 135. Проверки алгоритма на компьютере прошли, но производственный вызов, согласованный USB-контракт и команда приложения ещё не подключены. Новая ARM-сборка и её ресурсные доказательства не получены. Схема не превращает этот черновик в принятую функцию.')
para('2048 отсчётов при номинальных 50 квыб/с составляют окно 40,96 мс; между первым и последним отсчётами — 40,94 мс. Это свойства текущего программного профиля, а не доказанная длительность искры, измеренная частота или достаточная полоса готового прибора.')
para('Учебные аналоговые варианты A/B предназначены для низковольтных проверок и не являются готовым входом зажигания. До высоковольтного применения требуются проверка датчика, перегрузочной стойкости, питания, всех путей земли и развязки. Бесконтактный съём не доказывает изоляцию системы. Подача 19 В непосредственно на плату STM32 не допускается.')

d.add_page_break()
heading('6 Оформление и чтение схемы')
para('Использован код Э2: «Схема электрическая функциональная». Лист А3, 420 × 297 мм; рамка 20 мм слева и 5 мм с других сторон. Основная надпись — форма 1 размером 185 × 55 мм. Названия функциональных групп приведены непосредственно в прямоугольниках; вымышленные позиционные обозначения элементов не введены.')
para('Сплошные линии показывают внутренние функциональные связи. Штрихпунктиром обозначены группирующий контур STM32, внешние объекты и соответствующие внешние связи. Стрелки задают направление процесса. Подписи отделяют аналоговый сигнал, данные, команды, тактирование и питание. Ни одна стрелка не является монтажной инструкцией.')
para('Линии связей имеют толщину 0,35 мм, основные линии рамки — 0,7 мм. Применён прямой чертёжный шрифт OpenGOST типа Б: высота прописных букв преимущественно 3,5 мм, пояснений — 2,5 мм. В PDF шрифт встроен; в SVG надписи переведены в контуры. Печатать в масштабе 100 %, без подгонки страницы.')
para('Обозначение МТ.00.00.000 Э2 временное. Позиционные обозначения физических устройств должны быть согласованы с будущей принципиальной схемой Э3. Неизвестные фамилии, организация и подписи оставлены пустыми. Проектное оформление проверено по перечисленным стандартам; официальное утверждение или нормоконтроль кафедры не подразумевается.')
heading('Источники и проверяемые основания')
para('Для применимости использован официальный каталог КазСтандарт, проверенный 12.10.2026. Правила функциональных схем — ГОСТ 2.702-2011, раздел 5.2; общие правила и код Э2 — ГОСТ 2.701-2008. Геометрия основной надписи, формат, линии и шрифт сверены отдельно.')
refs=[('ГОСТ 2.701-2008 — виды и типы схем','38206'),('ГОСТ 2.702-2011 — электрические схемы','46766'),('ГОСТ 2.104-2006 — основные надписи','15565'),('ГОСТ 2.301-68 — форматы','14504'),('ГОСТ 2.303-68 — линии','14506'),('ГОСТ 2.304-81 — чертёжные шрифты','14507')]
for title,num in refs:
    p=d.add_paragraph();p.paragraph_format.first_line_indent=Mm(0);p.paragraph_format.space_after=Pt(2)
    link(p,title,'https://new-shop.ksm.kz/catalog/document/'+num+'/')
for title,url in [
 ('Изменение требований владельца: issue № 134','https://github.com/font-weight/stm32_motortester/issues/134'),
 ('Масштабирование по двум осям: issue № 136','https://github.com/font-weight/stm32_motortester/issues/136'),
 ('Черновик ядра «Запись сейчас»: PR № 135','https://github.com/font-weight/stm32_motortester/pull/135'),
 ('Драйвер ADC / TIM3 / DMA на проверенной основной версии','https://github.com/font-weight/stm32_motortester/blob/192fbb2ef9369bb1c32e11f97263094fca52763f/firmware/platform/adc_timer_dma.c'),
 ('Справка Disco-2: режимы осциллографа','https://motor-master.ru/downloads/help/osc.htm'),
 ('OpenGOST: шрифт и лицензия OFL 1.1','https://github.com/ingenium-am/open-gost-arm')]:
    p=d.add_paragraph();p.paragraph_format.first_line_indent=Mm(0);p.paragraph_format.space_after=Pt(2);link(p,title,url)

f=s.footer.paragraphs[0];f.alignment=WD_ALIGN_PARAGRAPH.CENTER
fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');f._p.append(fld)
for el in list(d.element.xpath('//w:pBdr')) + list(d.styles.element.xpath('//w:pBdr')):
    el.getparent().remove(el)
d.core_properties.title='Функциональная схема мотортестера — пояснение'
d.core_properties.subject='Проектная схема Э2: функции, связи, границы реализации'
d.save(B/'output/Описание_функциональной_схемы_мотортестера.docx')
print('Created editable block description')
